(1,'xanh-dien-anh','Xanh Điện Ảnh','Xanh Điện Ảnh là LUT phong cách teal, điện ảnh do Minh Color chỉnh màu. Kéo thả file .cube vào Premiere Pro, DaVinci Resolve, Final Cut Pro hoặc CapCut để áp ngay, rồi chỉnh cường độ cho hợp với cảnh quay của bạn.',1,'teal-orange',0,'PUBLISHED','http://localhost:9020/downbeat-public/lut/xanh-dien-anh/cover.jpg','BEFORE_AFTER','http://localhost:9020/downbeat-public/lut/xanh-dien-anh/before.jpg','http://localhost:9020/downbeat-public/lut/xanh-dien-anh/after.jpg',NULL,'lut/xanh-dien-anh.cube',948,33,18840,'2026-10-01 09:00:00',1),
