(32,'super-8','Super 8','Super 8 là LUT phong cách phim, vintage do Analog Lab chỉnh màu. Kéo thả file .cube vào Premiere Pro, DaVinci Resolve, Final Cut Pro hoặc CapCut để áp ngay, rồi chỉnh cường độ cho hợp với cảnh quay của bạn.',3,'co-dien',1,'PUBLISHED','http://localhost:9020/downbeat-public/lut/super-8/cover.jpg','BEFORE_AFTER','http://localhost:9020/downbeat-public/lut/super-8/before.jpg','http://localhost:9020/downbeat-public/lut/super-8/after.jpg',NULL,'lut/super-8.cube',948,33,8670,'2026-10-22 09:00:00',1),
(33,'mua-pho','Mưa Phố','Mưa Phố là LUT phong cách mưa, đường phố do Studio Kem chỉnh màu. Kéo thả file .cube vào Premiere Pro, DaVinci Resolve, Final Cut Pro hoặc CapCut để áp ngay, rồi chỉnh cường độ cho hợp với cảnh quay của bạn.',7,'lanh',0,'PUBLISHED','http://localhost:9020/downbeat-public/lut/mua-pho/cover.jpg','BEFORE_AFTER','http://localhost:9020/downbeat-public/lut/mua-pho/before.jpg','http://localhost:9020/downbeat-public/lut/mua-pho/after.jpg',NULL,'lut/mua-pho.cube',948,33,3980,'2026-11-03 09:00:00',1),
(34,'vlog-tuoi','Vlog Tươi','Vlog Tươi là LUT phong cách vlog, tươi do DownBeat Studio chỉnh màu. Kéo thả file .cube vào Premiere Pro, DaVinci Resolve, Final Cut Pro hoặc CapCut để áp ngay, rồi chỉnh cường độ cho hợp với cảnh quay của bạn.',2,'du-lich',0,'PUBLISHED','http://localhost:9020/downbeat-public/lut/vlog-tuoi/cover.jpg','BEFORE_AFTER','http://localhost:9020/downbeat-public/lut/vlog-tuoi/before.jpg','http://localhost:9020/downbeat-public/lut/vlog-tuoi/after.jpg',NULL,'lut/vlog-tuoi.cube',948,33,15640,'2026-09-09 09:00:00',1),
(35,'hoi-uc','Hồi Ức','Hồi Ức là LUT phong cách vintage, phai màu do Analog Lab chỉnh màu. Kéo thả file .cube vào Premiere Pro, DaVinci Resolve, Final Cut Pro hoặc CapCut để áp ngay, rồi chỉnh cường độ cho hợp với cảnh quay của bạn.',3,'co-dien',0,'PUBLISHED','http://localhost:9020/downbeat-public/lut/hoi-uc/cover.jpg','BEFORE_AFTER','http://localhost:9020/downbeat-public/lut/hoi-uc/before.jpg','http://localhost:9020/downbeat-public/lut/hoi-uc/after.jpg',NULL,'lut/hoi-uc.cube',948,33,6880,'2026-08-01 09:00:00',1),
(36,'anh-trang','Ánh Trăng','Ánh Trăng là LUT phong cách đêm, xanh do Mono Works chỉnh màu. Kéo thả file .cube vào Premiere Pro, DaVinci Resolve, Final Cut Pro hoặc CapCut để áp ngay, rồi chỉnh cường độ cho hợp với cảnh quay của bạn.',4,'lanh',1,'PUBLISHED','http://localhost:9020/downbeat-public/lut/anh-trang/cover.jpg','BEFORE_AFTER','http://localhost:9020/downbeat-public/lut/anh-trang/before.jpg','http://localhost:9020/downbeat-public/lut/anh-trang/after.jpg',NULL,'lut/anh-trang.cube',948,33,7710,'2026-10-27 09:00:00',1),
(37,'thu-nghiem-nhap','Thử Nghiệm Nháp','Thử Nghiệm Nháp là LUT phong cách phim, nháp do Analog Lab chỉnh màu. Kéo thả file .cube vào Premiere Pro, DaVinci Resolve, Final Cut Pro hoặc CapCut để áp ngay, rồi chỉnh cường độ cho hợp với cảnh quay của bạn.',3,'phim-nhua',0,'DRAFT','http://localhost:9020/downbeat-public/lut/thu-nghiem-nhap/cover.jpg','BEFORE_AFTER','http://localhost:9020/downbeat-public/lut/thu-nghiem-nhap/before.jpg','http://localhost:9020/downbeat-public/lut/thu-nghiem-nhap/after.jpg',NULL,'lut/thu-nghiem-nhap.cube',948,33,0,NULL,1),
(38,'hoang-hon-cu','Hoàng Hôn Cũ','Hoàng Hôn Cũ là LUT phong cách hoàng hôn, ấm do Minh Color chỉnh màu. Kéo thả file .cube vào Premiere Pro, DaVinci Resolve, Final Cut Pro hoặc CapCut để áp ngay, rồi chỉnh cường độ cho hợp với cảnh quay của bạn.',1,'am-ap',0,'HIDDEN','http://localhost:9020/downbeat-public/lut/hoang-hon-cu/cover.jpg','BEFORE_AFTER','http://localhost:9020/downbeat-public/lut/hoang-hon-cu/before.jpg','http://localhost:9020/downbeat-public/lut/hoang-hon-cu/after.jpg',NULL,'lut/hoang-hon-cu.cube',948,33,99999,'2026-11-04 09:00:00',1);
